class View:
    def __init__(self):
        self.rows = []
        self.notes = {}
        self.loading = False
        self.error = None
        self.seq = 0
        self.last_request_id = None
        self.accepted_rows = []

    def begin(self, query):
        self.seq += 1
        self.last_request_id = self.seq
        self.error = None
        self.loading = True
        return self.seq

    def finish(self, request_id, rows):
        if request_id != self.last_request_id:
            return False

        self.rows = rows
        self.accepted_rows = rows.copy()
        self.loading = False
        return True

    def get_accepted_rows(self):
        return self.accepted_rows.copy()
